"use client";

import { useCallback, useEffect, useMemo, useState, type ReactNode } from "react";
import {
  AlertTriangle, BarChart3, BedDouble, Check, CheckCircle2, ClipboardCheck, CloudOff, CreditCard,
  Gauge, Gift, Layers3, Loader2, MessageSquareText, Plus, RefreshCw, Save, SlidersHorizontal,
  Sparkles, Star, Wrench, ChevronLeft, ChevronRight,
} from "lucide-react";
import apiClient from "@/lib/apiClient";
import DatePickerField from "@/components/DatePickerField";
import ShareBookingButton from "@/components/ShareBookingButton";
import { useNrms } from "../_components/NrmsProvider";

type Tab = "rates" | "readiness" | "service" | "guest" | "portfolio" | "growth";
type Dashboard = {
  ratePlans: any[]; restrictions: any[]; onboarding: any | null; serviceCases: any[]; paymentRequests: any[];
  journeys: any[]; forecast: any | null; recommendations: any[]; loyalty: any[]; reviews: any[]; portfolios: any[];
  roomTypes: any[]; roomUnits: any[]; eligibleReservations: any[]; ownerProperties: any[];
  reviewInsights: { responses: number; overall: number | null; categories: Array<{ key: string; label: string; average: number; responses: number }>; selectedCategories: string[]; availableCategories: Array<{ key: string; label: string }>; platformIntent: Record<string, number> } | null;
};
type OfflineMutation = { clientMutationId: string; action: "SERVICE_CASE_CREATE" | "SERVICE_CASE_STATUS" | "ROOM_HOUSEKEEPING_STATUS"; targetId?: number; baseVersion?: number; payload: Record<string, unknown> };

const TABS: Array<{ id: Tab; label: string; icon: typeof SlidersHorizontal }> = [
  { id: "rates", label: "Rates", icon: SlidersHorizontal }, { id: "readiness", label: "Readiness", icon: ClipboardCheck },
  { id: "service", label: "Service desk", icon: Wrench }, { id: "guest", label: "Guest journey", icon: MessageSquareText },
  { id: "portfolio", label: "Portfolio", icon: Layers3 }, { id: "growth", label: "Growth", icon: Gauge },
];

const inputClass = "box-border min-h-10 w-full min-w-0 rounded-lg border border-neutral-300 bg-white px-3 text-sm text-neutral-900 outline-none transition focus:border-emerald-700 focus:ring-2 focus:ring-emerald-100 disabled:bg-neutral-100";
const buttonClass = "inline-flex min-h-10 items-center justify-center gap-2 rounded-md border-0 bg-[#075e54] px-4 text-xs font-bold text-white transition hover:bg-[#064b43] disabled:cursor-not-allowed disabled:bg-neutral-200 disabled:text-neutral-500";

function money(value: unknown, currency = "TZS") { return new Intl.NumberFormat(undefined, { style: "currency", currency, maximumFractionDigits: 0 }).format(Number(value || 0)); }
function shortDate(value: string) { return new Date(value).toLocaleDateString(undefined, { day: "numeric", month: "short", year: "numeric" }); }
function Label({ children }: { children: ReactNode }) { return <label className="grid gap-1.5 text-xs font-bold text-neutral-700">{children}</label>; }
function DateField({ label, aria, value, onChange, min }: { label: string; aria: string; value: string; onChange: (iso: string) => void; min?: string }) { return <div className="grid min-w-0 gap-1.5"><span className="text-xs font-bold text-neutral-700">{label}</span><DatePickerField label={aria} value={value} onChangeAction={onChange} min={min} size="sm" widthClassName="w-full" /></div>; }
const PAGE_SIZE = 12;
function paged<T>(items: T[], page: number, size = PAGE_SIZE) { const pages = Math.max(1, Math.ceil(items.length / size)); const current = Math.min(Math.max(1, page), pages); return { items: items.slice((current - 1) * size, current * size), pages, current, total: items.length }; }
function Pager({ current, pages, total, size = PAGE_SIZE, onPage }: { current: number; pages: number; total: number; size?: number; onPage: (page: number) => void }) {
  if (total <= size) return null;
  const from = (current - 1) * size + 1;
  const to = Math.min(total, current * size);
  return <div className="mt-3 flex flex-wrap items-center justify-between gap-2 border-t border-neutral-100 pt-3">
    <p className="m-0 text-[10px] font-semibold text-neutral-500">Showing {from} to {to} of {total}</p>
    <div className="flex items-center gap-1">
      <button type="button" disabled={current <= 1} onClick={() => onPage(current - 1)} className="inline-flex h-8 items-center gap-1 rounded-md border border-neutral-200 bg-white px-2.5 text-[10px] font-bold text-neutral-600 disabled:cursor-not-allowed disabled:opacity-40"><ChevronLeft className="h-3.5 w-3.5" />Prev</button>
      <span className="px-1.5 text-[10px] font-bold text-neutral-500">{current} / {pages}</span>
      <button type="button" disabled={current >= pages} onClick={() => onPage(current + 1)} className="inline-flex h-8 items-center gap-1 rounded-md border border-neutral-200 bg-white px-2.5 text-[10px] font-bold text-neutral-600 disabled:cursor-not-allowed disabled:opacity-40">Next<ChevronRight className="h-3.5 w-3.5" /></button>
    </div>
  </div>;
}
function Empty({ children }: { children: ReactNode }) { return <div className="rounded-lg border border-dashed border-neutral-300 bg-neutral-50 px-4 py-8 text-center text-sm text-neutral-500">{children}</div>; }
function Status({ value }: { value: string }) { const positive = ["ACTIVE", "VERIFIED", "COMPLETED", "RESOLVED", "APPLIED", "SENT"].includes(value); const attention = ["BLOCKED", "FAILED", "URGENT", "OVERDUE"].includes(value); return <span className={`inline-flex rounded-full px-2.5 py-1 text-[10px] font-bold uppercase tracking-wide ${positive ? "bg-emerald-50 text-emerald-700" : attention ? "bg-red-50 text-red-700" : "bg-amber-50 text-amber-800"}`}>{value.replaceAll("_", " ")}</span>; }
function Section({ title, copy, action, children }: { title: string; copy: string; action?: ReactNode; children: ReactNode }) { return <section className="overflow-hidden rounded-xl border border-neutral-200 bg-white shadow-sm"><header className="flex flex-wrap items-start justify-between gap-3 border-b border-neutral-100 px-5 py-4"><div><h2 className="m-0 text-base font-bold text-neutral-950">{title}</h2><p className="mb-0 mt-1 max-w-2xl text-xs leading-5 text-neutral-500">{copy}</p></div>{action}</header><div className="p-5">{children}</div></section>; }

function deviceId() {
  const key = "nrms-offline-device-id"; let value = localStorage.getItem(key);
  if (!value) { value = crypto.randomUUID(); localStorage.setItem(key, value); }
  return value;
}
function queueKey(propertyId: number) { return `nrms-offline-queue:${propertyId}`; }
function readQueue(propertyId: number): OfflineMutation[] { try { return JSON.parse(localStorage.getItem(queueKey(propertyId)) || "[]"); } catch { return []; } }
function cacheKey(propertyId: number) { return `nrms-offline-snapshot:${propertyId}`; }

export default function NrmsControlsPage() {
  const { selectedPropertyId, selectedProperty } = useNrms();
  const [tab, setTab] = useState<Tab>("rates"); const [data, setData] = useState<Dashboard | null>(null);
  const [loading, setLoading] = useState(true); const [busy, setBusy] = useState<string | null>(null); const [message, setMessage] = useState<string | null>(null); const [error, setError] = useState<string | null>(null);
  const [online, setOnline] = useState(true); const [queued, setQueued] = useState(0);
  const [rate, setRate] = useState({ code: "BAR", name: "Best available rate", roomTypeId: "", adjustmentType: "BASE", adjustment: "0", mealPlan: "ROOM_ONLY", defaultMinStay: "1", isDefault: true });
  const [restriction, setRestriction] = useState({ name: "", roomTypeId: "", startDate: "", endDate: "", minStay: "", stopSell: false, closedToArrival: false, closedToDeparture: false });
  const [season, setSeason] = useState({ ratePlanId: "", name: "", startDate: "", endDate: "", adjustmentType: "OFFSET", adjustment: "0", minStay: "" });
  const [service, setService] = useState({ title: "", category: "MAINTENANCE", priority: "NORMAL", roomUnitId: "", description: "" });
  const [journey, setJourney] = useState({ name: "", trigger: "PRE_ARRIVAL", offsetMinutes: "-1440", channel: "SMS", message: "Hello {{guest}}, we look forward to welcoming you to {{property}}." });
  const [payment, setPayment] = useState({ reservationId: "", kind: "DEPOSIT", amount: "", dueAt: "" });
  const [portfolio, setPortfolio] = useState({ name: "", propertyIds: [] as number[] });
  const [loyaltyPage, setLoyaltyPage] = useState(1); const [reviewPage, setReviewPage] = useState(1);

  const load = useCallback(async () => {
    if (!selectedPropertyId) return; setLoading(true); setError(null);
    try { const response = await apiClient.get<Dashboard>(`/api/owner/nrms/market-readiness/${selectedPropertyId}`); setData(response.data); localStorage.setItem(cacheKey(selectedPropertyId), JSON.stringify({ savedAt: new Date().toISOString(), data: response.data })); }
    catch (requestError: any) { try { const snapshot = JSON.parse(localStorage.getItem(cacheKey(selectedPropertyId)) || "null"); if (snapshot?.data) { setData(snapshot.data); setMessage(`Showing the last synced hotel snapshot from ${new Date(snapshot.savedAt).toLocaleString()}.`); } else setError(requestError?.response?.data?.error || "Hotel controls could not be loaded."); } catch { setError(requestError?.response?.data?.error || "Hotel controls could not be loaded."); } }
    finally { setLoading(false); }
  }, [selectedPropertyId]);

  const replay = useCallback(async () => {
    if (!selectedPropertyId || !navigator.onLine) return; const mutations = readQueue(selectedPropertyId); if (!mutations.length) return;
    try { const response = await apiClient.post(`/api/owner/nrms/market-readiness/${selectedPropertyId}/offline/replay`, { deviceId: deviceId(), mutations }); const results = response.data?.results ?? []; const retry = mutations.filter((item) => !results.some((result: any) => result.clientMutationId === item.clientMutationId && result.status === "APPLIED")); localStorage.setItem(queueKey(selectedPropertyId), JSON.stringify(retry)); setQueued(retry.length); if (results.some((result: any) => result.status === "CONFLICT")) setError("An offline update conflicts with a newer server version. Review it in Service desk."); if (!retry.length) await load(); }
    catch { /* Preserve the queue until connectivity is genuinely restored. */ }
  }, [load, selectedPropertyId]);

  useEffect(() => { void load(); }, [load]);
  useEffect(() => { const sync = () => { setOnline(navigator.onLine); if (selectedPropertyId) setQueued(readQueue(selectedPropertyId).length); if (navigator.onLine) void replay(); }; sync(); window.addEventListener("online", sync); window.addEventListener("offline", sync); return () => { window.removeEventListener("online", sync); window.removeEventListener("offline", sync); }; }, [replay, selectedPropertyId]);

  const act = async (key: string, request: () => Promise<unknown>, success: string) => { setBusy(key); setError(null); setMessage(null); try { await request(); setMessage(success); await load(); } catch (requestError: any) { setError(requestError?.response?.data?.error || "The action could not be completed."); } finally { setBusy(null); } };
  const createRate = () => act("rate", () => apiClient.post(`/api/owner/nrms/market-readiness/${selectedPropertyId}/rate-plans`, { ...rate, roomTypeId: rate.roomTypeId ? Number(rate.roomTypeId) : null, adjustment: Number(rate.adjustment), defaultMinStay: Number(rate.defaultMinStay) }), "Rate plan saved.");
  const createSeason = () => act("season", () => apiClient.post(`/api/owner/nrms/market-readiness/${selectedPropertyId}/rate-plans/${season.ratePlanId}/seasons`, { name: season.name, startDate: season.startDate, endDate: season.endDate, adjustmentType: season.adjustmentType, adjustment: Number(season.adjustment), minStay: season.minStay ? Number(season.minStay) : null }), "Seasonal rate saved.");
  const createRestriction = () => act("restriction", () => apiClient.post(`/api/owner/nrms/market-readiness/${selectedPropertyId}/restrictions`, { ...restriction, roomTypeId: restriction.roomTypeId ? Number(restriction.roomTypeId) : null, minStay: restriction.minStay ? Number(restriction.minStay) : null }), "Restriction saved.");
  const createService = async () => {
    if (!selectedPropertyId || !service.title.trim()) return; const payload = { ...service, roomUnitId: service.roomUnitId ? Number(service.roomUnitId) : null };
    if (!navigator.onLine) { const queue = readQueue(selectedPropertyId); queue.push({ clientMutationId: crypto.randomUUID(), action: "SERVICE_CASE_CREATE", payload }); localStorage.setItem(queueKey(selectedPropertyId), JSON.stringify(queue)); setQueued(queue.length); setService((current) => ({ ...current, title: "", description: "" })); setMessage("Service case saved on this device and will sync when connection returns."); return; }
    await act("service", () => apiClient.post(`/api/owner/nrms/market-readiness/${selectedPropertyId}/service-cases`, payload), "Service case opened.");
  };
  const updateCase = (item: any, status: string) => act(`case-${item.id}`, () => apiClient.patch(`/api/owner/nrms/market-readiness/${selectedPropertyId}/service-cases/${item.id}`, { version: item.version, status }), `Case ${status.toLowerCase().replaceAll("_", " ")}.`);
  const progress = useMemo(() => { const checks = data?.onboarding?.checks ?? []; return checks.length ? Math.round(checks.filter((item: any) => item.status === "VERIFIED").length / checks.length * 100) : 0; }, [data]);
  const loyaltyView = useMemo(() => paged(data?.loyalty ?? [], loyaltyPage), [data, loyaltyPage]);
  const reviewView = useMemo(() => paged(data?.reviews ?? [], reviewPage), [data, reviewPage]);
  const recoveryQueue = useMemo(() => (data?.reviews ?? []).filter((item: any) => item.needsRecovery && !item.recoveredAt), [data]);
  const toggleReviewCategory = (key: string) => {
    const current: string[] = data?.reviewInsights?.selectedCategories ?? [];
    const next = current.includes(key) ? current.filter((item) => item !== key) : [...current, key];
    return act(`review-category-${key}`, () => apiClient.put(`/api/owner/nrms/market-readiness/${selectedPropertyId}/review-categories`, { categories: next }), "Review questions updated.");
  };

  if (loading && !data) return <div className="flex min-h-[50vh] items-center justify-center text-neutral-400"><Loader2 className="h-6 w-6 animate-spin" /></div>;

  return <div id="nrms-controls" className="mx-auto max-w-[1500px] space-y-5 pb-10">
    <style dangerouslySetInnerHTML={{ __html: `#nrms-controls *{box-sizing:border-box}#nrms-controls input[type=checkbox]{appearance:none;-webkit-appearance:none;width:1.05rem;height:1.05rem;flex:0 0 auto;border:1.5px solid #cbd5e1;border-radius:5px;background:#fff;cursor:pointer;position:relative;vertical-align:middle;transition:border-color .15s,background-color .15s}#nrms-controls input[type=checkbox]:hover{border-color:#059669}#nrms-controls input[type=checkbox]:checked{background:#059669;border-color:#059669}#nrms-controls input[type=checkbox]:checked::after{content:"";position:absolute;left:5px;top:1.5px;width:4px;height:9px;border:solid #fff;border-width:0 2px 2px 0;transform:rotate(45deg)}#nrms-controls input[type=checkbox]:focus-visible{outline:2px solid #10b981;outline-offset:1px}` }} />
    <header className="flex flex-wrap items-end justify-between gap-4">
      <div><p className="m-0 text-[10px] font-bold uppercase tracking-[0.18em] text-emerald-700">Hotel operating system</p><h1 className="mb-0 mt-1 text-2xl font-bold tracking-tight text-neutral-950">Hotel controls</h1><p className="mb-0 mt-1 max-w-3xl text-sm text-neutral-500">Rates, readiness, service recovery and growth controls for {selectedProperty?.title || "this property"}.</p></div>
      <div className="flex flex-wrap items-center gap-2"><ShareBookingButton propertyId={selectedPropertyId} propertyTitle={selectedProperty?.title} /><span className={`inline-flex min-h-9 items-center gap-2 rounded-full px-3 text-xs font-bold ${online ? "bg-emerald-50 text-emerald-700" : "bg-amber-50 text-amber-800"}`}>{online ? <CheckCircle2 className="h-4 w-4" /> : <CloudOff className="h-4 w-4" />}{online ? (queued ? `${queued} waiting to sync` : "Synced") : `${queued} saved offline`}</span><button type="button" onClick={() => void load()} className="inline-flex h-10 items-center gap-2 rounded-md border border-neutral-200 bg-white px-3 text-xs font-bold text-neutral-600"><RefreshCw className={`h-4 w-4 ${loading ? "animate-spin" : ""}`} />Refresh</button></div>
    </header>
    {(message || error) && <div className={`flex items-start gap-3 rounded-lg border px-4 py-3 text-sm ${error ? "border-red-200 bg-red-50 text-red-800" : "border-emerald-200 bg-emerald-50 text-emerald-800"}`}>{error ? <AlertTriangle className="mt-0.5 h-4 w-4 shrink-0" /> : <Check className="mt-0.5 h-4 w-4 shrink-0" />}<span>{error || message}</span></div>}
    <nav className="overflow-x-auto rounded-lg border border-neutral-200 bg-white p-1.5 shadow-sm [scrollbar-width:none] [&::-webkit-scrollbar]:hidden" aria-label="Hotel controls">
      <div className="flex min-w-max gap-1.5 lg:min-w-0">
        {TABS.map((item) => {
          const Icon = item.icon;
          const active = tab === item.id;
          return (
            <button
              key={item.id}
              type="button"
              onClick={() => setTab(item.id)}
              aria-current={active ? "page" : undefined}
              className={`group relative inline-flex min-h-12 shrink-0 cursor-pointer appearance-none items-center gap-2.5 rounded-md border px-3.5 text-[11px] font-bold outline-none transition focus-visible:ring-2 focus-visible:ring-emerald-500 focus-visible:ring-offset-1 lg:flex-1 lg:justify-center ${active ? "border-emerald-200 bg-emerald-50/80 text-emerald-900 shadow-sm" : "border-transparent bg-transparent text-neutral-500 hover:border-neutral-200 hover:bg-neutral-50 hover:text-neutral-900"}`}
            >
              <span className={`flex h-7 w-7 shrink-0 items-center justify-center rounded-md transition ${active ? "bg-emerald-800 text-white shadow-sm" : "bg-neutral-100 text-neutral-500 group-hover:bg-white group-hover:text-neutral-700"}`}>
                <Icon className="h-3.5 w-3.5" />
              </span>
              <span className="whitespace-nowrap">{item.label}</span>
              {active && <span className="absolute inset-x-3 bottom-0 h-0.5 rounded-t-full bg-emerald-700" aria-hidden="true" />}
            </button>
          );
        })}
      </div>
    </nav>

    {tab === "rates" && <div className="grid gap-5 xl:grid-cols-[.85fr_1.15fr]">
      <div className="space-y-5"><Section title="New rate plan" copy="Create one reusable commercial product, then add seasonal overrides without changing room inventory."><div className="grid gap-4 sm:grid-cols-2"><Label>Plan name<input className={inputClass} value={rate.name} onChange={(event) => setRate({ ...rate, name: event.target.value })} /></Label><Label>Code<input className={inputClass} value={rate.code} onChange={(event) => setRate({ ...rate, code: event.target.value })} /></Label><Label>Room type<select className={inputClass} value={rate.roomTypeId} onChange={(event) => setRate({ ...rate, roomTypeId: event.target.value })}><option value="">All room types</option>{data?.roomTypes.map((room) => <option key={room.id} value={room.id}>{room.name}</option>)}</select></Label><Label>Meal plan<select className={inputClass} value={rate.mealPlan} onChange={(event) => setRate({ ...rate, mealPlan: event.target.value })}><option value="ROOM_ONLY">Room only</option><option value="BREAKFAST">Breakfast</option><option value="HALF_BOARD">Half board</option><option value="FULL_BOARD">Full board</option></select></Label><Label>Rate method<select className={inputClass} value={rate.adjustmentType} onChange={(event) => setRate({ ...rate, adjustmentType: event.target.value })}><option value="BASE">Use room base rate</option><option value="FIXED">Fixed rate</option><option value="OFFSET">Amount adjustment</option><option value="PERCENT">Percentage adjustment</option></select></Label><Label>Value<input type="number" className={inputClass} value={rate.adjustment} onChange={(event) => setRate({ ...rate, adjustment: event.target.value })} /></Label><Label>Minimum stay<input type="number" min="1" className={inputClass} value={rate.defaultMinStay} onChange={(event) => setRate({ ...rate, defaultMinStay: event.target.value })} /></Label><label className="flex items-center gap-2 self-end pb-3 text-xs font-bold text-neutral-700"><input type="checkbox" checked={rate.isDefault} onChange={(event) => setRate({ ...rate, isDefault: event.target.checked })} />Default direct rate</label></div><button className={`${buttonClass} mt-5`} disabled={busy === "rate"} onClick={createRate}>{busy === "rate" ? <Loader2 className="h-4 w-4 animate-spin" /> : <Save className="h-4 w-4" />}Save plan</button></Section>
      <Section title="Seasonal override" copy="Apply one fixed, amount or percentage adjustment to a selected plan for a controlled period."><div className="grid gap-4 sm:grid-cols-2"><Label>Rate plan<select className={inputClass} value={season.ratePlanId} onChange={(event) => setSeason({ ...season, ratePlanId: event.target.value })}><option value="">Select plan</option>{data?.ratePlans.map((plan) => <option key={plan.id} value={plan.id}>{plan.name}</option>)}</select></Label><Label>Season name<input className={inputClass} value={season.name} onChange={(event) => setSeason({ ...season, name: event.target.value })} placeholder="High season" /></Label><DateField label="From" aria="Season start date" value={season.startDate} onChange={(iso) => setSeason({ ...season, startDate: iso })} /><DateField label="To" aria="Season end date" value={season.endDate} onChange={(iso) => setSeason({ ...season, endDate: iso })} min={season.startDate || undefined} /><Label>Adjustment<select className={inputClass} value={season.adjustmentType} onChange={(event) => setSeason({ ...season, adjustmentType: event.target.value })}><option value="OFFSET">Amount</option><option value="PERCENT">Percentage</option><option value="FIXED">Fixed nightly rate</option></select></Label><Label>Value<input type="number" className={inputClass} value={season.adjustment} onChange={(event) => setSeason({ ...season, adjustment: event.target.value })} /></Label></div><button className={`${buttonClass} mt-5`} disabled={busy === "season" || !season.ratePlanId || !season.name || !season.startDate || !season.endDate} onClick={createSeason}><Plus className="h-4 w-4" />Add season</button></Section>
      <Section title="New restriction" copy="Apply minimum stay, arrival/departure closure or stop-sell for a controlled date range."><div className="grid gap-4 sm:grid-cols-2"><Label>Name<input className={inputClass} value={restriction.name} onChange={(event) => setRestriction({ ...restriction, name: event.target.value })} placeholder="Eid minimum stay" /></Label><Label>Room type<select className={inputClass} value={restriction.roomTypeId} onChange={(event) => setRestriction({ ...restriction, roomTypeId: event.target.value })}><option value="">Entire property</option>{data?.roomTypes.map((room) => <option key={room.id} value={room.id}>{room.name}</option>)}</select></Label><DateField label="From" aria="Restriction start date" value={restriction.startDate} onChange={(iso) => setRestriction({ ...restriction, startDate: iso })} /><DateField label="To" aria="Restriction end date" value={restriction.endDate} onChange={(iso) => setRestriction({ ...restriction, endDate: iso })} min={restriction.startDate || undefined} /><Label>Minimum stay<input type="number" min="1" className={inputClass} value={restriction.minStay} onChange={(event) => setRestriction({ ...restriction, minStay: event.target.value })} /></Label><div className="grid gap-2 pt-1 text-xs font-semibold text-neutral-700"><label><input type="checkbox" checked={restriction.stopSell} onChange={(event) => setRestriction({ ...restriction, stopSell: event.target.checked })} /> <span className="ml-1">Stop sell</span></label><label><input type="checkbox" checked={restriction.closedToArrival} onChange={(event) => setRestriction({ ...restriction, closedToArrival: event.target.checked })} /> <span className="ml-1">Closed to arrival</span></label><label><input type="checkbox" checked={restriction.closedToDeparture} onChange={(event) => setRestriction({ ...restriction, closedToDeparture: event.target.checked })} /> <span className="ml-1">Closed to departure</span></label></div></div><button className={`${buttonClass} mt-5`} disabled={busy === "restriction" || !restriction.name || !restriction.startDate || !restriction.endDate} onClick={createRestriction}><Plus className="h-4 w-4" />Add restriction</button></Section></div>
      <div className="space-y-5"><Section title="Active rate architecture" copy="Room rates remain the base truth; plans and seasons describe how they are sold.">{data?.ratePlans.length ? <div className="divide-y divide-neutral-100 border-y border-neutral-100">{data.ratePlans.map((plan) => <div key={plan.id} className="py-4"><div className="flex items-start justify-between gap-3"><div><div className="flex flex-wrap items-center gap-2"><h3 className="m-0 text-sm font-bold text-neutral-900">{plan.name}</h3>{plan.isDefault && <span className="rounded-full bg-emerald-50 px-2 py-0.5 text-[9px] font-bold text-emerald-700">DEFAULT</span>}</div><p className="mb-0 mt-1 text-xs text-neutral-500">{plan.code} · {plan.roomType?.name || "All room types"} · {plan.mealPlan.replaceAll("_", " ").toLowerCase()}</p></div><Status value={plan.status} /></div>{plan.seasons?.length > 0 && <div className="mt-3 grid gap-2 sm:grid-cols-2">{plan.seasons.map((season: any) => <div key={season.id} className="rounded-lg border border-neutral-200 bg-neutral-50 px-3 py-2"><p className="m-0 text-xs font-bold">{season.name}</p><p className="mb-0 mt-1 text-[10px] text-neutral-500">{shortDate(season.startDate)} to {shortDate(season.endDate)} · {season.adjustmentType.toLowerCase()} {Number(season.adjustment)}</p></div>)}</div>}</div>)}</div> : <Empty>No rate plans yet. Start with a default Best Available Rate.</Empty>}</Section><Section title="Restrictions calendar" copy="Only active controls are shown. These rules are available to both direct booking and channel delivery.">{data?.restrictions.length ? <div className="space-y-2">{data.restrictions.map((item) => <div key={item.id} className="grid gap-2 rounded-lg border border-neutral-200 p-3 sm:grid-cols-[1fr_auto] sm:items-center"><div><p className="m-0 text-xs font-bold text-neutral-900">{item.name}</p><p className="mb-0 mt-1 text-[10px] text-neutral-500">{item.roomType?.name || "Entire property"} · {shortDate(item.startDate)} to {shortDate(item.endDate)}</p></div><div className="flex gap-1">{item.stopSell && <Status value="STOP_SELL" />}{item.minStay && <span className="rounded-full bg-neutral-100 px-2 py-1 text-[10px] font-bold">{item.minStay} night min</span>}</div></div>)}</div> : <Empty>No active restrictions.</Empty>}</Section></div>
    </div>}

    {tab === "readiness" && <div className="grid gap-5 xl:grid-cols-[1.1fr_.9fr]"><Section title="Guided readiness" copy="A required, evidence-backed checklist replaces informal go-live decisions." action={!data?.onboarding || data.onboarding.status !== "IN_PROGRESS" ? <button className={buttonClass} disabled={busy === "start"} onClick={() => act("start", () => apiClient.post(`/api/owner/nrms/market-readiness/${selectedPropertyId}/onboarding/start`), "Readiness workflow started.")}><Plus className="h-4 w-4" />Start assessment</button> : undefined}>{data?.onboarding ? <><div className="mb-5 flex items-end justify-between gap-4"><div><p className="m-0 text-3xl font-bold text-neutral-950">{progress}%</p><p className="mb-0 mt-1 text-xs text-neutral-500">Required controls verified</p></div><Status value={data.onboarding.status} /></div><div className="mb-5 h-2 overflow-hidden rounded-full bg-neutral-100"><div className="h-full bg-emerald-600 transition-all" style={{ width: `${progress}%` }} /></div><div className="divide-y divide-neutral-100 border-y border-neutral-100">{data.onboarding.checks.map((check: any) => <div key={check.id} className="flex items-center justify-between gap-4 py-3"><div className="flex items-center gap-3"><span className={`flex h-7 w-7 items-center justify-center rounded-full ${check.status === "VERIFIED" ? "bg-emerald-100 text-emerald-700" : "bg-neutral-100 text-neutral-400"}`}>{check.status === "VERIFIED" ? <Check className="h-4 w-4" /> : <span className="h-2 w-2 rounded-full bg-current" />}</span><div><p className="m-0 text-xs font-bold text-neutral-900">{check.label}</p><p className="mb-0 mt-0.5 text-[10px] text-neutral-400">{check.key}</p></div></div><button type="button" disabled={busy === `check-${check.id}`} onClick={() => act(`check-${check.id}`, () => apiClient.patch(`/api/owner/nrms/market-readiness/${selectedPropertyId}/onboarding/checks/${check.id}`, { status: check.status === "VERIFIED" ? "PENDING" : "VERIFIED", evidence: { confirmedInWorkspace: true } }), "Readiness evidence updated.")} className="min-h-8 rounded-md border border-neutral-200 bg-white px-3 text-[10px] font-bold text-neutral-600">{check.status === "VERIFIED" ? "Reopen" : "Verify"}</button></div>)}</div><button className={`${buttonClass} mt-5 w-full`} disabled={progress !== 100 || busy === "complete" || data.onboarding.status === "COMPLETED"} onClick={() => act("complete", () => apiClient.post(`/api/owner/nrms/market-readiness/${selectedPropertyId}/onboarding/complete`), "Property readiness completed.")}><ClipboardCheck className="h-4 w-4" />{data.onboarding.status === "COMPLETED" ? "Readiness approved" : "Complete readiness review"}</button></> : <Empty>No readiness assessment has been started.</Empty>}</Section><Section title="Safe onboarding design" copy="Every setup run keeps validation and rollback evidence so imported data can be inspected before go-live."><div className="space-y-4">{[["Validate before activation", "Room inventory, rates, payment instructions and staff access are checked as a group."], ["No silent overwrite", "Imported identifiers are snapshotted and every checklist decision records who verified it."], ["Controlled rollback", "A setup can be reversed from its captured snapshot without deleting live reservations."], ["Dry-run inventory", "The final gate requires a reservation and availability test before completion."]].map(([title, copy], index) => <div key={title} className="flex gap-3"><span className="flex h-7 w-7 shrink-0 items-center justify-center rounded-full bg-emerald-50 text-xs font-bold text-emerald-700">{index + 1}</span><div><p className="m-0 text-xs font-bold text-neutral-900">{title}</p><p className="mb-0 mt-1 text-xs leading-5 text-neutral-500">{copy}</p></div></div>)}</div></Section></div>}

    {tab === "service" && <div className="grid gap-5 xl:grid-cols-[.75fr_1.25fr]"><Section title="Open service case" copy="Create a tracked maintenance or guest request. If the network drops, the case is safely queued on this device."><div className="grid gap-4"><Label>Issue title<input className={inputClass} value={service.title} onChange={(event) => setService({ ...service, title: event.target.value })} placeholder="Air conditioner not cooling" /></Label><div className="grid gap-4 sm:grid-cols-2"><Label>Category<select className={inputClass} value={service.category} onChange={(event) => setService({ ...service, category: event.target.value })}><option value="MAINTENANCE">Maintenance</option><option value="GUEST_REQUEST">Guest request</option><option value="SAFETY">Safety</option><option value="IT">IT</option><option value="OTHER">Other</option></select></Label><Label>Priority<select className={inputClass} value={service.priority} onChange={(event) => setService({ ...service, priority: event.target.value })}><option value="LOW">Low</option><option value="NORMAL">Normal</option><option value="HIGH">High</option><option value="URGENT">Urgent</option></select></Label></div><Label>Room<select className={inputClass} value={service.roomUnitId} onChange={(event) => setService({ ...service, roomUnitId: event.target.value })}><option value="">No room</option>{data?.roomUnits.map((room) => <option key={room.id} value={room.id}>{room.code}</option>)}</select></Label><Label>Description<textarea className={`${inputClass} min-h-24 py-3`} value={service.description} onChange={(event) => setService({ ...service, description: event.target.value })} /></Label></div><button className={`${buttonClass} mt-5 w-full`} disabled={busy === "service" || !service.title.trim()} onClick={() => void createService()}>{busy === "service" ? <Loader2 className="h-4 w-4 animate-spin" /> : <Wrench className="h-4 w-4" />}Open case</button></Section><Section title="Service board" copy="Optimistic version checks prevent an offline or stale device from overwriting a newer update.">{data?.serviceCases.length ? <div className="space-y-2">{data.serviceCases.map((item) => <article key={item.id} className="rounded-lg border border-neutral-200 p-4"><div className="flex flex-wrap items-start justify-between gap-3"><div><div className="flex flex-wrap items-center gap-2"><p className="m-0 text-sm font-bold text-neutral-950">{item.title}</p><Status value={item.priority} /></div><p className="mb-0 mt-1 text-[10px] font-semibold text-neutral-400">{item.reference} · {item.category.replaceAll("_", " ").toLowerCase()} {item.roomUnit?.code ? `· Room ${item.roomUnit.code}` : ""}</p></div><Status value={item.status} /></div>{item.description && <p className="mb-0 mt-3 text-xs leading-5 text-neutral-600">{item.description}</p>}<div className="mt-4 flex flex-wrap gap-2">{item.status === "OPEN" && <button onClick={() => updateCase(item, "ACKNOWLEDGED")} className="min-h-8 rounded-md border border-neutral-200 bg-white px-3 text-[10px] font-bold">Acknowledge</button>}{["OPEN", "ACKNOWLEDGED", "BLOCKED"].includes(item.status) && <button onClick={() => updateCase(item, "IN_PROGRESS")} className="min-h-8 rounded-md border border-blue-200 bg-blue-50 px-3 text-[10px] font-bold text-blue-700">Start work</button>}{item.status !== "RESOLVED" && item.status !== "CANCELLED" && <button onClick={() => updateCase(item, "RESOLVED")} className="min-h-8 rounded-md border border-emerald-200 bg-emerald-50 px-3 text-[10px] font-bold text-emerald-700">Resolve</button>}</div></article>)}</div> : <Empty>No service cases are open.</Empty>}</Section></div>}

    {tab === "guest" && <div className="grid gap-5 xl:grid-cols-2"><div className="space-y-5"><Section title="Automated guest journey" copy="Templates schedule against booking and stay events. Messages use the existing consent-aware delivery layer."><div className="grid gap-4 sm:grid-cols-2"><Label>Template name<input className={inputClass} value={journey.name} onChange={(event) => setJourney({ ...journey, name: event.target.value })} placeholder="Arrival reminder" /></Label><Label>Trigger<select className={inputClass} value={journey.trigger} onChange={(event) => setJourney({ ...journey, trigger: event.target.value })}><option value="BOOKED">Booked</option><option value="PRE_ARRIVAL">Pre arrival</option><option value="CHECK_IN">Check in</option><option value="PRE_DEPARTURE">Pre departure</option><option value="CHECK_OUT">Check out</option></select></Label><Label>Offset in minutes<input type="number" className={inputClass} value={journey.offsetMinutes} onChange={(event) => setJourney({ ...journey, offsetMinutes: event.target.value })} /></Label><Label>Channel<select className={inputClass} value={journey.channel} onChange={(event) => setJourney({ ...journey, channel: event.target.value })}><option value="SMS">SMS</option><option value="EMAIL">Email</option></select></Label><label className="grid gap-1.5 text-xs font-bold text-neutral-700 sm:col-span-2">Message<textarea className={`${inputClass} min-h-24 py-3`} value={journey.message} onChange={(event) => setJourney({ ...journey, message: event.target.value })} /></label></div><div className="mt-5 flex flex-wrap gap-2"><button className={buttonClass} disabled={!journey.name || busy === "journey"} onClick={() => act("journey", () => apiClient.post(`/api/owner/nrms/market-readiness/${selectedPropertyId}/journeys`, { ...journey, offsetMinutes: Number(journey.offsetMinutes) }), "Journey template saved.")}><Save className="h-4 w-4" />Save template</button><button className="inline-flex min-h-10 items-center gap-2 rounded-md border border-neutral-200 bg-white px-4 text-xs font-bold text-neutral-700" onClick={() => act("schedule", () => apiClient.post(`/api/owner/nrms/market-readiness/${selectedPropertyId}/journeys/schedule`), "Guest journeys scheduled.")}><Sparkles className="h-4 w-4" />Schedule eligible stays</button></div></Section><Section title="Journey library" copy="Clear operational messages, not marketing broadcasts.">{data?.journeys.length ? <div className="divide-y divide-neutral-100 border-y border-neutral-100">{data.journeys.map((item) => <div key={item.id} className="flex items-center justify-between gap-3 py-3"><div><p className="m-0 text-xs font-bold">{item.name}</p><p className="mb-0 mt-1 text-[10px] text-neutral-500">{item.trigger.replaceAll("_", " ")} · {item.channel} · {item._count.deliveries} scheduled</p></div><Status value={item.active ? "ACTIVE" : "INACTIVE"} /></div>)}</div> : <Empty>No journey templates.</Empty>}</Section></div><div className="space-y-5"><Section title="Direct guest payment request" copy="NRMS sends the hotel’s own payment instructions. Money received is still recorded immutably on the folio."><div className="grid gap-4 sm:grid-cols-2"><label className="grid gap-1.5 text-xs font-bold text-neutral-700 sm:col-span-2">Reservation<select className={inputClass} value={payment.reservationId} onChange={(event) => setPayment({ ...payment, reservationId: event.target.value })}><option value="">Select a guest stay</option>{data?.eligibleReservations.map((item) => <option key={item.id} value={item.id}>{item.guestProfile?.fullName || "Guest"} · {item.receiptNumber || `Reservation ${item.id}`}</option>)}</select></label><Label>Request type<select className={inputClass} value={payment.kind} onChange={(event) => setPayment({ ...payment, kind: event.target.value })}><option value="DEPOSIT">Deposit</option><option value="BALANCE">Balance</option><option value="INCIDENTAL">Incidental</option></select></Label><Label>Amount<input type="number" min="1" className={inputClass} value={payment.amount} onChange={(event) => setPayment({ ...payment, amount: event.target.value })} /></Label><div className="sm:col-span-2"><DateField label="Due at" aria="Payment due date" value={payment.dueAt} onChange={(iso) => setPayment({ ...payment, dueAt: iso })} /></div></div><button className={`${buttonClass} mt-5`} disabled={!payment.reservationId || !payment.amount || busy === "payment"} onClick={() => act("payment", () => apiClient.post(`/api/owner/nrms/market-readiness/${selectedPropertyId}/payment-requests`, { reservationId: Number(payment.reservationId), kind: payment.kind, amount: Number(payment.amount), currency: "TZS", dueAt: payment.dueAt ? new Date(payment.dueAt).toISOString() : null }), "Payment request created.")}><CreditCard className="h-4 w-4" />Create request</button></Section><Section title="Payment requests" copy="Status is operational evidence; it never replaces the folio payment record.">{data?.paymentRequests.length ? <div className="space-y-2">{data.paymentRequests.map((item) => <div key={item.id} className="flex items-center justify-between gap-3 rounded-lg border border-neutral-200 p-3"><div><p className="m-0 text-xs font-bold">{item.reservation.guestProfile?.fullName || item.reservation.receiptNumber}</p><p className="mb-0 mt-1 text-[10px] text-neutral-500">{item.kind.toLowerCase()} · {money(item.amount, item.currency)}</p></div><Status value={item.status} /></div>)}</div> : <Empty>No payment requests.</Empty>}</Section></div></div>}

    {tab === "portfolio" && <div className="grid gap-5 xl:grid-cols-[.8fr_1.2fr]"><Section title="Create portfolio" copy="Group properties you own for one operational and performance view."><Label>Portfolio name<input className={inputClass} value={portfolio.name} onChange={(event) => setPortfolio({ ...portfolio, name: event.target.value })} placeholder="Northern circuit hotels" /></Label><div className="mt-4 divide-y divide-neutral-100 border-y border-neutral-100">{data?.ownerProperties.map((property) => <label key={property.id} className="flex items-center justify-between gap-3 py-3 text-xs font-semibold text-neutral-700"><span>{property.title}</span><input type="checkbox" checked={portfolio.propertyIds.includes(property.id)} onChange={(event) => setPortfolio({ ...portfolio, propertyIds: event.target.checked ? [...portfolio.propertyIds, property.id] : portfolio.propertyIds.filter((id) => id !== property.id) })} /></label>)}</div><button className={`${buttonClass} mt-5 w-full`} disabled={!portfolio.name || !portfolio.propertyIds.length || busy === "portfolio"} onClick={() => act("portfolio", () => apiClient.post(`/api/owner/nrms/market-readiness/${selectedPropertyId}/portfolios`, portfolio), "Portfolio created.")}><Layers3 className="h-4 w-4" />Create portfolio</button></Section><Section title="Property groups" copy="Each property stays isolated for operations while portfolio membership supports consolidated management.">{data?.portfolios.length ? <div className="grid gap-3 md:grid-cols-2">{data.portfolios.map((item) => <article key={item.id} className="rounded-lg border border-neutral-200 p-4"><div className="flex items-center justify-between gap-2"><h3 className="m-0 text-sm font-bold">{item.name}</h3><span className="text-[10px] font-bold text-neutral-400">{item.properties.length} properties</span></div><div className="mt-3 space-y-2">{item.properties.map((link: any) => <div key={link.propertyId} className="flex items-center gap-2 text-xs text-neutral-600"><BedDouble className="h-3.5 w-3.5 text-emerald-700" />{link.property.title}</div>)}</div></article>)}</div> : <Empty>No portfolios yet. A single property continues to work independently.</Empty>}</Section></div>}

    {tab === "growth" && <div className="space-y-5"><div className="grid gap-4 md:grid-cols-4">{[["Forward occupancy", data?.forecast ? `${(Number(data.forecast.occupancyPct) * 100).toFixed(1)}%` : "Not computed", BarChart3], ["ADR", data?.forecast ? money(data.forecast.adr) : "—", Gauge], ["Loyal guests", String(data?.loyalty.length || 0), Gift], ["Review requests", String(data?.reviews.length || 0), Star]].map(([label, value, Icon]: any) => <div key={label} className="rounded-xl border border-neutral-200 bg-white p-4 shadow-sm"><Icon className="h-5 w-5 text-emerald-700" /><p className="mb-0 mt-4 text-2xl font-bold text-neutral-950">{value}</p><p className="mb-0 mt-1 text-xs text-neutral-500">{label}</p></div>)}</div><div className="grid gap-5 xl:grid-cols-2"><Section title="Forecast and pricing guidance" copy="Recommendations are explainable and remain pending until a manager decides to apply them." action={<button className={buttonClass} disabled={busy === "forecast"} onClick={() => act("forecast", () => apiClient.post(`/api/owner/nrms/market-readiness/${selectedPropertyId}/forecast/recompute`, { horizonDays: 30 }), "Forecast and pricing guidance refreshed.")}><RefreshCw className="h-4 w-4" />Recompute</button>}>{data?.recommendations.length ? <div className="max-h-[28rem] space-y-2 overflow-y-auto pr-1">{data.recommendations.map((item) => <div key={item.id} className="grid gap-3 rounded-lg border border-neutral-200 p-3 sm:grid-cols-[1fr_auto] sm:items-center"><div><p className="m-0 text-xs font-bold">{item.roomType.name} · {shortDate(item.stayDate)}</p><p className="mb-0 mt-1 text-[10px] leading-4 text-neutral-500">{item.reason}</p></div><div className="text-right"><p className="m-0 text-xs text-neutral-400 line-through">{money(item.currentRate, item.currency)}</p><p className="mb-0 mt-1 text-sm font-bold text-emerald-700">{money(item.recommendedRate, item.currency)}</p></div></div>)}</div> : <Empty>Recompute the forecast to create explainable recommendations.</Empty>}</Section><div className="space-y-5"><Section title="Loyalty intelligence" copy="Tier and points are rebuilt only from completed, property-linked stays." action={<button className="inline-flex min-h-9 items-center gap-2 rounded-md border border-neutral-200 bg-white px-3 text-[10px] font-bold" onClick={() => act("loyalty", () => apiClient.post(`/api/owner/nrms/market-readiness/${selectedPropertyId}/loyalty/rebuild`), "Loyalty records rebuilt from completed stays.")}><Gift className="h-3.5 w-3.5" />Rebuild</button>}>{data?.loyalty.length ? <><div className="max-h-72 overflow-y-auto pr-1"><div className="grid gap-2 sm:grid-cols-2">{loyaltyView.items.map((item) => <div key={item.id} className="flex items-center justify-between gap-3 rounded-lg border border-neutral-200 px-3 py-2.5"><div className="min-w-0"><p className="m-0 truncate text-xs font-bold text-neutral-900">{item.guestProfile.fullName}</p><p className="mb-0 mt-0.5 text-[10px] text-neutral-500">{item.lifetimeStays} {item.lifetimeStays === 1 ? "stay" : "stays"} · {money(item.lifetimeSpend)}</p></div><Status value={item.tier} /></div>)}</div></div><Pager current={loyaltyView.current} pages={loyaltyView.pages} total={loyaltyView.total} onPage={setLoyaltyPage} /></> : <Empty>No completed-stay loyalty records.</Empty>}</Section><Section title="Verified-stay reputation" copy="Queue private review requests only after NRMS has recorded checkout." action={<button className="inline-flex min-h-9 items-center gap-2 rounded-md border border-neutral-200 bg-white px-3 text-[10px] font-bold" onClick={() => act("reviews", () => apiClient.post(`/api/owner/nrms/market-readiness/${selectedPropertyId}/reviews/queue`), "Verified-stay review requests queued.")}><Star className="h-3.5 w-3.5" />Queue eligible</button>}>{data?.reviews.length ? <><div className="max-h-72 overflow-y-auto pr-1"><div className="grid gap-2 sm:grid-cols-2">{reviewView.items.map((item) => <div key={item.id} className="flex items-center justify-between gap-2 rounded-lg border border-neutral-200 px-3 py-2"><span className="flex min-w-0 items-center gap-2"><Star className="h-3.5 w-3.5 shrink-0 text-amber-500" /><span className="truncate text-xs font-bold text-neutral-900">{item.guestProfile?.fullName || item.reservation.receiptNumber}</span></span><Status value={item.status} /></div>)}</div></div><Pager current={reviewView.current} pages={reviewView.pages} total={reviewView.total} onPage={setReviewPage} /></> : <Empty>No review requests queued.</Empty>}</Section>
      <Section title="What guests actually rate" copy="Category scores from verified stays. Choose which questions departing guests are asked, so a property without a restaurant is never asked to rate one.">
        <div className="space-y-4">
          <div>
            <p className="m-0 text-[10px] font-bold uppercase tracking-[0.14em] text-neutral-500">Questions asked at checkout</p>
            <div className="mt-2 flex flex-wrap gap-1.5">
              {(data?.reviewInsights?.availableCategories ?? []).map((category) => {
                const on = (data?.reviewInsights?.selectedCategories ?? []).includes(category.key);
                return <button key={category.key} type="button" disabled={busy === `review-category-${category.key}`} onClick={() => void toggleReviewCategory(category.key)}
                  className={`min-h-8 rounded-full border px-3 text-[10px] font-bold ${on ? "border-emerald-700 bg-emerald-700 text-white" : "border-neutral-300 bg-white text-neutral-600"}`}>{category.label}</button>;
              })}
            </div>
          </div>
          {data?.reviewInsights?.categories.length ? <div>
            <p className="m-0 text-[10px] font-bold uppercase tracking-[0.14em] text-neutral-500">Averages from {data.reviewInsights.responses} {data.reviewInsights.responses === 1 ? "response" : "responses"}{data.reviewInsights.overall ? ` · overall ${data.reviewInsights.overall.toFixed(2)}` : ""}</p>
            <div className="mt-2 space-y-1.5">
              {data.reviewInsights.categories.map((category) => <div key={category.key} className="flex items-center gap-3">
                <span className="w-40 shrink-0 truncate text-[11px] text-neutral-600">{category.label}</span>
                <span className="h-1.5 flex-1 rounded-full bg-neutral-100"><span className={`block h-1.5 rounded-full ${category.average < 3 ? "bg-red-500" : category.average < 4 ? "bg-amber-500" : "bg-emerald-600"}`} style={{ width: `${(category.average / 5) * 100}%` }} /></span>
                <span className="w-8 shrink-0 text-right text-[11px] font-bold text-neutral-900">{category.average.toFixed(1)}</span>
              </div>)}
            </div>
          </div> : <Empty>No category scores yet.</Empty>}
          {data?.reviewInsights && (data.reviewInsights.platformIntent.YES || data.reviewInsights.platformIntent.MAYBE || data.reviewInsights.platformIntent.NO) ? <div>
            <p className="m-0 text-[10px] font-bold uppercase tracking-[0.14em] text-neutral-500">Would book through NoLSAF again</p>
            <p className="mb-0 mt-1 text-xs text-neutral-700">Yes {data.reviewInsights.platformIntent.YES} · Maybe {data.reviewInsights.platformIntent.MAYBE} · No {data.reviewInsights.platformIntent.NO}</p>
          </div> : null}
          {recoveryQueue.length ? <div className="rounded-lg border border-amber-200 bg-amber-50 p-3">
            <p className="m-0 text-[11px] font-bold text-amber-950">{recoveryQueue.length} {recoveryQueue.length === 1 ? "guest needs" : "guests need"} a personal follow-up</p>
            <p className="mb-0 mt-0.5 text-[10px] leading-4 text-amber-900/80">These guests rated the stay 3 or below. They were not asked to recommend the property.</p>
            <div className="mt-2 space-y-1.5">
              {recoveryQueue.slice(0, 8).map((item: any) => <div key={item.id} className="flex items-center justify-between gap-2 rounded-md bg-white px-2.5 py-2">
                <span className="min-w-0"><span className="block truncate text-[11px] font-bold text-neutral-900">{item.guestProfile?.fullName || item.reservation.receiptNumber}</span><span className="block truncate text-[10px] text-neutral-500">{item.rating} of 5{item.feedback ? ` · ${item.feedback}` : ""}</span></span>
                <button type="button" disabled={busy === `recovered-${item.id}`} onClick={() => void act(`recovered-${item.id}`, () => apiClient.post(`/api/owner/nrms/market-readiness/${selectedPropertyId}/reviews/${item.id}/recovered`, {}), "Recovery task closed.")}
                  className="min-h-8 shrink-0 rounded-md border border-neutral-200 bg-white px-2.5 text-[10px] font-bold text-neutral-700">Contacted</button>
              </div>)}
            </div>
          </div> : null}
        </div>
      </Section></div></div></div>}
  </div>;
}
